export type LibraryErrorCode =
  | 'project_not_found'
  | 'variant_not_found'
  | 'workspace_unavailable'
  | 'folder_picker_busy'
  | 'folder_picker_unavailable'
  | 'preview_unavailable';

export class LibraryError extends Error {
  constructor(
    readonly code: LibraryErrorCode,
    message: string,
  ) {
    super(message);
    this.name = 'LibraryError';
  }
}
